from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = 'gdp.xlsx'
workbook = load_workbook(path)
task = workbook['Task']

for start_row, end_row in ((12, 17), (19, 24), (26, 31)):
    for row in range(start_row, end_row + 1):
        for column in range(8, 13):
            column_letter = get_column_letter(column)
            task.cell(row, column).value = (
                f'=INDEX(Data!$H$21:$M$40,MATCH($D{row},Data!$B$21:$B$40,0),'
                f'MATCH({column_letter}$9,Data!$H$4:$M$4,0))'
            )

for row in range(35, 41):
    source_row = row - 23
    for column in range(8, 13):
        column_letter = get_column_letter(column)
        task.cell(row, column).value = (
            f'=({column_letter}{source_row}-{column_letter}{source_row + 7})/'
            f'{column_letter}{source_row + 14}'
        )

summary_functions = {
    42: 'MIN',
    43: 'MAX',
    44: 'MEDIAN',
    45: 'AVERAGE',
    46: 'PERCENTILE.INC',
    47: 'PERCENTILE.INC',
}
for row, function in summary_functions.items():
    for column in range(8, 13):
        column_letter = get_column_letter(column)
        if row == 46:
            formula = f'={function}({column_letter}$35:{column_letter}$40,0.25)'
        elif row == 47:
            formula = f'={function}({column_letter}$35:{column_letter}$40,0.75)'
        else:
            formula = f'={function}({column_letter}$35:{column_letter}$40)'
        task.cell(row, column).value = formula

for column in range(8, 13):
    column_letter = get_column_letter(column)
    task.cell(50, column).value = (
        f'=SUMPRODUCT({column_letter}$35:{column_letter}$40,'
        f'{column_letter}$26:{column_letter}$31)/SUM({column_letter}$26:{column_letter}$31)'
    )

workbook.calculation.fullCalcOnLoad = True
workbook.calculation.forceFullCalc = True
workbook.calculation.calcMode = 'auto'
workbook.save(path)
